-- Migration: 0220 qData 元数据业务展示数据。
-- Purpose: 替换旧元数据演示记录，导入授权源站任务、实例、库表、文件及不可变版本；不导入任何登录凭据或可执行连接。
-- Depends on: 0218_governance_metadata-display.sql；当前单租户平台基线及完整元数据表。
-- Target: 已有 PostgreSQL 平台库；执行前停止元数据采集工作进程；新库直接使用已包含本脚本的全量基线。
-- Repeatable: 是；导入标记存在即不再改动，重复执行保留用户后续维护结果。
-- Rollback: 首次执行会删除旧元数据及其标签绑定，无法从脚本恢复；执行前备份 dh_governance_meta_* 表，失败由事务整体回滚。
-- 仅替换 Governance 元数据领域；不创建或修改 System 用户及 DataForge 连接，远端身份引用使用隔离编号。
-- 源端当前态 40 表及 728 字段；排除已删除表残留的 20 条孤立字段。历史结构按源端只读版本接口保留。
-- 源端表 41 的 V1.0.2 对比接口因重复版本失败，本地该版本明确标记为当前结构导入，不宣称恢复该历史接口。
-- 所有导入任务调度均停止，日志中的源端连接信息已移除；展示名称不能作为认证或授权依据。

BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';
DO $seed$
BEGIN
    LOCK TABLE dh_governance_meta_collect_task,dh_governance_meta_collect_instance,
        dh_governance_meta_collect_log,dh_governance_meta_db,dh_governance_meta_table,
        dh_governance_meta_column,dh_governance_meta_file,dh_governance_meta_table_snapshot,dh_governance_meta_change,
        dh_governance_meta_tag_rel IN SHARE ROW EXCLUSIVE MODE;
    IF EXISTS (SELECT 1 FROM dh_governance_meta_db WHERE display_snapshot->>'bundleId'='qdata-metadata-20261022') THEN
        RETURN;
    END IF;
    IF EXISTS (SELECT 1 FROM dh_governance_meta_collect_instance WHERE deleted=0 AND status IN (0,1)) THEN
        RAISE EXCEPTION '仍有排队或运行的采集实例，请停止采集并处理活动实例后重试';
    END IF;
    DELETE FROM dh_governance_meta_tag_rel WHERE object_type IN (1,2,3);
    DELETE FROM dh_governance_meta_change;
    DELETE FROM dh_governance_meta_collect_log;
    DELETE FROM dh_governance_meta_table_snapshot;
    DELETE FROM dh_governance_meta_column;
    DELETE FROM dh_governance_meta_table;
    DELETE FROM dh_governance_meta_db;
    DELETE FROM dh_governance_meta_file;
    DELETE FROM dh_governance_meta_collect_instance;
    DELETE FROM dh_governance_meta_collect_task;







    PERFORM setval('dh_governance_meta_collect_task_seq', GREATEST((SELECT COALESCE(MAX(id),1) FROM dh_governance_meta_collect_task),1), true);
    PERFORM setval('dh_governance_meta_collect_instance_seq', GREATEST((SELECT COALESCE(MAX(id),1) FROM dh_governance_meta_collect_instance),1), true);
    PERFORM setval('dh_governance_meta_db_seq', GREATEST((SELECT COALESCE(MAX(id),1) FROM dh_governance_meta_db),1), true);
    PERFORM setval('dh_governance_meta_table_seq', GREATEST((SELECT COALESCE(MAX(id),1) FROM dh_governance_meta_table),1), true);
    PERFORM setval('dh_governance_meta_column_seq', GREATEST((SELECT COALESCE(MAX(id),1) FROM dh_governance_meta_column),1), true);
    PERFORM setval('dh_governance_meta_file_seq', GREATEST((SELECT COALESCE(MAX(id),1) FROM dh_governance_meta_file),1), true);
    PERFORM setval('dh_governance_meta_table_snapshot_seq', GREATEST((SELECT COALESCE(MAX(id),1) FROM dh_governance_meta_table_snapshot),1), true);
    PERFORM setval('dh_governance_meta_collect_log_seq', GREATEST((SELECT COALESCE(MAX(id),1) FROM dh_governance_meta_collect_log),1), true);
END
$seed$;
COMMIT;
